def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]
    if denominator == 0:
        return {"value": None, "trace": {"numerator": numerator, "denominator": denominator, "output_meta": {"currency": None, "scale": None, "unit": "ratio"}}}
    value = numerator / denominator
    return {
        "value": value,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "output_meta": {"currency": None, "scale": None, "unit": "ratio"},
        },
    }
